insert into public.monthly_commentary
  (client_id, month, headline, summary, platform_narratives, section_notes, conclusion, status, published_at)
values ('5f0c9a1e-7b2d-4c3e-9a41-0d6b8e2f1a01', '2026-07-01', 'A New Strategy. Real Leads. Immediate Results.', 'On July 14, Wieler Roofing moved its full paid advertising budget from Google Ads to Meta Ads. In the 23 days that followed, the campaign generated 23 new leads, reached 13,020 people, and transformed the brand''s digital presence across every channel.

July 2026 was the month everything changed. The campaign produced 23 leads at $31.27 per lead and delivered a 2.18% click-through rate, all on a partial month of spend totaling $719.19. These are not vanity metrics. These are real people in West Texas who saw the ad, clicked through, and raised their hand for roofing services.

The impact was felt across every platform. Facebook page views surged 5,800% compared to the prior month. Paid Social became the number one source of website traffic, driving 154 sessions at a 98.7% engagement rate. The roof inspection landing page alone captured 387 views and 379 key events, confirming that the paid audience is landing on the right page and taking action.',
        '{"meta_facebook":{"headline":"21,239 Views, 362 Engagements","body":"The Facebook page experienced unprecedented growth in July, driven by the Meta Ads launch on July 14. The page was relatively quiet in the first two weeks of the month, then took off once the paid campaign went live. 60% of all engagement came from non-followers, proving the content is reaching a brand new audience."},"meta_instagram":{"headline":"2,254 Views, 94 Interactions","body":"Instagram continued to build steady momentum in July, with strong viewership and a highly local audience. Reels were the dominant format, generating 1,400 views compared to 822 for standard posts. The audience is 89.2% U.S.-based, and 95.8% of followers are English speakers."},"meta_ads":{"headline":"23 Leads Generated in the First 23 Days","body":"The campaign launched with immediate results, reaching 13,020 people in its first 23 days. With a 2.18% click-through rate and a frequency of 2.19, the West Texas audience is seeing the ads multiple times and actively engaging. The $719.19 in spend covers a partial month, which makes the lead volume even more significant."},"ga4":{"headline":"98.6% Engagement Across 430 Sessions","body":"The website held a 98.6% engagement rate, the highest quality traffic the site has seen to date. Paid Social became the top traffic source, and the roof inspection page captured 60% of all visits."}}'::jsonb, '{"content":"Short-form video led engagement across platforms. On Instagram, Reels captured the large majority of views, while on Facebook, Link Posts and Reels drove 75% of all audience interaction.","demographics":"The audience aligns with homeowners and property decision makers in the West Texas market, and is nearly evenly split by gender: 50.6% men and 49.4% women.","discovery":"On Facebook, 58% of views came from the Feed and 36.4% from Reels, showing strong algorithmic discovery. On Instagram, 58.5% of views came from non-followers, confirming the content is reaching beyond the existing audience.","video":"Reels remain the strongest format: 1,400 Instagram Reels views and 35% of all Facebook engagement."}'::jsonb,
        'July 2026 was a transformative month for Wieler Roofing. The decision to pivot from Google Ads to Meta Ads on July 14 produced immediate, high-impact results across every digital channel, driving a 5,800% increase in Facebook visibility and making Paid Social the leading source of highly engaged website traffic.

The website maintained an exceptional 98.6% engagement rate, with the roof inspection page capturing 60% of all site traffic. Instagram grew steadily to 213 followers, with Reels driving the majority of views and "Welcome to West Texas" proving to be the most effective organic post. Across all platforms, the data confirms that the move to Meta Ads has elevated the brand''s digital presence in the West Texas market.', 'published', '2026-08-08T15:00:00Z');

